"""Replay an existing encoder candidate on the current compiler integration."""
import ast,contextlib,hashlib,itertools,json,subprocess,sys,types
from pathlib import Path
from unittest.mock import patch
ROOT=Path.cwd();HARNESS=Path('/private/tmp/sdkbench-product-conformance-20261121');CANDIDATE='9eff313ea69ca304b521782884acfe117c961031';ENCODER='flagquantum/core/ir/__init__.py'
def git(root,*args):return subprocess.check_output(['git',*args],cwd=root,text=True,timeout=20).strip()
assert git(HARNESS,'rev-parse','HEAD')=='9aa9260920984e2ca05bcb293abb885fccd9c144'
assert not git(HARNESS,'status','--porcelain')
sys.path.insert(0,str(HARNESS/'src'))
import flagquantum.core.ir as ir
original=ir._encode_value
candidate_source=git(ROOT,'show',f'{CANDIDATE}:{ENCODER}')
node=next(x for x in ast.parse(candidate_source).body if isinstance(x,ast.FunctionDef) and x.name=='_encode_value')
namespace=dict(vars(ir));exec(compile(ast.Module(body=[node],type_ignores=[]),f'{CANDIDATE}:{ENCODER}','exec'),namespace);candidate=namespace['_encode_value']
source=git(ROOT,'show','HEAD:benchmarks/compiler_cz_identity_prefix.py')
control=types.ModuleType('container_encoding_controls');control.__file__=str(ROOT/'benchmarks/compiler_cz_identity_prefix.py');exec(compile(source,control.__file__,'exec'),control.__dict__)
report={'implementation_commit':git(ROOT,'rev-parse','HEAD'),'source_commit':git(HARNESS,'rev-parse','HEAD'),'target_revision':CANDIDATE,'scope':'existing encoder AST only on current compiler; inspected development controls, not prospective or qualified performance evidence','runner_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'candidate_source_sha256':hashlib.sha256(candidate_source.encode()).hexdigest(),'current_source_sha256':hashlib.sha256((ROOT/ENCODER).read_bytes()).hexdigest(),'helper_sha256':hashlib.sha256(source.encode()).hexdigest(),'complete':False,'rows':[],'failures':[]}
OUTPUT=Path('/private/tmp/fq-current-container-encoding-controls-20261122.json')
@contextlib.contextmanager
def variant(name):
 late_aliases=[];installed=[]
 with contextlib.ExitStack() as stack:
  if name=='candidate':
   for module_name,module in tuple(sys.modules.items()):
    if module_name.startswith('flagquantum.') and module is not None:
     for attribute,value in tuple(vars(module).items()):
      if value is original:
       installed.append((module,attribute));stack.enter_context(patch.object(module,attribute,candidate))
  try:
   yield
  finally:
   # A lazily imported module can bind the patched function after entry.
   # Restore those aliases too, so a following baseline cannot inherit it.
   for module_name,module in tuple(sys.modules.items()):
    if module_name.startswith('flagquantum.') and module is not None:
     for attribute,value in tuple(vars(module).items()):
      if value is candidate and (module,attribute) not in installed:
       late_aliases.append((module,attribute))
 for module,attribute in late_aliases:
  setattr(module,attribute,original)
 assert not any(value is candidate for name,module in tuple(sys.modules.items()) if name.startswith('flagquantum.') and module is not None for value in tuple(vars(module).values()))
for index,case in enumerate(itertools.product((6,8,12),('qaoa','ising','hopping','qft','repetition'),('line','ring','grid','sparse'))):
 observations={}
 try:
  for name in (['baseline','candidate'] if index%2==0 else ['candidate','baseline']):
   with variant(name):observations[name]=control._observe(case,HARNESS)
  comparable=('metrics','selected_strategy','restored_swap_count','rewrite_count','maximum_rewrite_inputs','normalized_output_sha256')
  assert all(observations['baseline'][key]==observations['candidate'][key] for key in comparable),(case,observations)
  report['rows'].append({'case':case,'observations':observations,'equal':True})
 except Exception as error:
  report['failures'].append({'case':case,'observations':observations,'exception':type(error).__name__,'message':str(error)})
 OUTPUT.write_text(json.dumps(report,indent=2)+'\n')
 print(index+1,case,'paired acceptance' if not report['failures'] else 'failure retained',flush=True)
report['complete']=True;OUTPUT.write_text(json.dumps(report,indent=2)+'\n')
raise SystemExit(bool(report['failures']))

